import json
import time
from datetime import datetime

import requests

NODE_URL = "https://api.upow.ai/"

# api.upow.ai/get_address_info?address=DYSNNWvB6hboBBPXD74HeLoNgqg2xU1cheSD8wLDQGe2z&transactions_count_limit=50
