address = "DcohkkTbfrkY7ZZZabT2vCX6qagWPaRbxGJtF7m7TZry3"


def get_address_info(address: str, transactions_count_limit=50, page=1):
    request = requests.get(
        f"{NODE_URL}get_address_info",
        {"address": address, "transactions_count_limit": transactions_count_limit, "show_pending": False, "page": page},
    )
    result = request.json()["result"]
    tx_inputs = []
    # pending_spent_outputs = [
    #     tuple(output) for output in result["pending_spent_outputs"]
    # ]
    # for spendable_tx_input in result["spendable_outputs"]:
    #     if (
    #             spendable_tx_input["tx_hash"],
    #             spendable_tx_input["index"],
    #     ) in pending_spent_outputs:
    #         continue
    #     tx_input = TransactionInput(
    #         spendable_tx_input["tx_hash"], spendable_tx_input["index"]
    #     )
    #     tx_input.amount = Decimal(str(spendable_tx_input["amount"]))
    #     tx_input.public_key = string_to_point(address)
    #     tx_inputs.append(tx_input)
    return result["transactions"]


def get_block(block: str):
    request = requests.get(
        f"{NODE_URL}get_block",
        {"block": block})
    result = request.json()["result"]
    return result


transactions = []
page = 0
while True:
    page += 1
    res = get_address_info(address, page=page)
    print(page, len(res))
    transactions.extend(res)
    print('transactions', len(transactions))
    time.sleep(0.5)
    if len(res) < 50:
        break

with open(f'addr_{address}.json', 'w') as f:
    json.dump(transactions, f)

f = open(f'addr_{address}.json')
# returns JSON object as
# a dictionary
data = json.load(f)
data.reverse()
for i, data in enumerate(data):
    if "transaction_type" in data:
        block = get_block(data["block_hash"])["block"]
        print(i, block["id"], datetime.utcfromtimestamp(block['timestamp']), end=" ")
        print(data["hash"], data["transaction_type"], [output["type"] for output in data["outputs"]])

# Closing file
f.close()

